1	package net.officefloor.hq.app;
2	
3	import java.math.BigDecimal;
4	import jakarta.persistence.Column;
5	import jakarta.persistence.Entity;
6	import jakarta.persistence.GeneratedValue;
7	import jakarta.persistence.GenerationType;
8	import jakarta.persistence.Id;
9	import jakarta.persistence.Table;
10	
11	/**
12	 * One line of an invoice: a thing the user is charging for — a description, how many, and the price
13	 * each. Maps the {@code invoice_line_items} table (Flyway V15__invoice_line_items.sql); the id is
14	 * IDENTITY-generated on create. The unit price is a {@link BigDecimal} because it is money (fixed
15	 * scale, no float drift). A line's own amount is its quantity times its unit price, and an invoice's
16	 * amount is the sum of its lines' amounts.
17	 */
18	@Entity
19	@Table(name = "invoice_line_items")
20	public class InvoiceLineItem {
21	
22	    @Id
23	    @GeneratedValue(strategy = GenerationType.IDENTITY)
24	    private Long id;
